<?php require_once '../config/helpers.php';require_customer();$services=$pdo->query('SELECT * FROM services WHERE is_active=1 ORDER BY name')->fetchAll();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$sid=(int)($_POST['service_id']??0);$date=$_POST['event_date']??'';$time=$_POST['event_time']??'';$loc=trim($_POST['event_location']??'');$addr=trim($_POST['full_address']??'');$notes=trim($_POST['notes']??'');$validDate=preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)&&$date>=date('Y-m-d');$validTime=preg_match('/^\d{2}:\d{2}$/',$time);$check=$pdo->prepare('SELECT id FROM services WHERE id=? AND is_active=1');$check->execute([$sid]);if(!$check->fetch()||!$validDate||!$validTime||$loc===''||$addr===''){$error='Please complete all required fields and choose a future date.';}else{$st=$pdo->prepare('INSERT INTO bookings(customer_id,service_id,event_date,event_time,event_location,full_address,notes) VALUES(?,?,?,?,?,?,?)');$st->execute([$_SESSION['customer_id'],$sid,$date,$time,$loc,$addr,$notes]);flash('Your booking request was submitted. We will contact you to confirm.');redirect('dashboard.php');}}$page_title='Book Appointment';$asset_prefix='../';$home_link='../index.php';$services_link='../index.php#services';$login_link='../login.php';$register_link='../register.php';$logout_link='../logout.php';$customer_link='dashboard.php';include '../includes/header.php'; ?><div class="form-wrap wide panel"><h1 class="section-title">Book Your Appointment</h1><p class="muted center">Please provide the event date, preferred time and exact venue details.</p><?php if($error): ?><div class="alert error"><?= e($error) ?></div><?php endif; ?><form method="post" class="form"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><div class="form-row"><div><label>Select service *</label><select name="service_id" required><option value="">Choose a service</option><?php foreach($services as $s): ?><option value="<?= (int)$s['id'] ?>"><?= e($s['name']) ?></option><?php endforeach; ?></select></div><div><label>Event date *</label><input type="date" name="event_date" min="<?= date('Y-m-d') ?>" required></div></div><div class="form-row"><div><label>Preferred time *</label><input type="time" name="event_time" required></div><div><label>City / Area *</label><input name="event_location" placeholder="e.g. Coimbatore, Gandhipuram" required maxlength="180"></div></div><div><label>Full event address *</label><textarea name="full_address" placeholder="House / hall name, street, area, landmark and PIN code" required></textarea></div><div><label>Additional notes (optional)</label><textarea name="notes" placeholder="Event type, number of people, preferred look..."></textarea></div><button>Submit Booking Request</button></form></div><?php include '../includes/footer.php'; ?>
